    if(P.equippedSec&&P.equippedSec!=='none'&&P.equippedSec!=='fists'&&P.weapons.indexOf(P.equippedSec)<0) P.equippedSec='none';
    if((P.equippedSec||'none')===P.equipped) P.equippedSec='none';
  }
  try{ saveProfile(); }catch(_s){}
